INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (4, 0, "そうなんです、胸が苦しくて\n仕方ないんです……\nや、やっぱり重病なんでしょうか……", 0, 1007402, 1007402036, 0.5, 0, 100211, 1, 11);
