INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (5, 0, "そうね、逞しい人たちだものね……\nはあ、懐かしい。あの人たちには昔、\nよく研究のことで因縁をつけられたわ。", 0, 1007404, 1007404055, 0.5, 0, 117531, 1, 11);
INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES ("", "", 0, "", 1007404, 1007404056, "", "", 0, "", 91);
