INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (4, 0, "やれやれ、嘆かわしい老人たちめ。\n学問に貴賤なし──\nぼくらはみな等しく学びの信徒だ、\n文系だ理系だと諍うことの愚かしさよ。", 0, 1007404, 1007404064, 0.5, 0, 111011, 1, 11);
