INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (5, 0, "否。\n今日は患者として参ったのだ。\n医薬の道に長じた御身の助けを得たい。", 0, 1007405, 1007405043, 0.5, 0, 111011, 1, 11);
INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES ("", "", "", "", 1007405, 1007405044, "", "", 0, "", 91);
