INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (7, 0, "あら、穏やかじゃないわね。\nいいわ、聞きましょう。どうぞ？", 0, 1007405, 1007405048, 0.5, 0, 117531, 1, 11);
INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES ("", "", "", "", 1007405, 1007405049, "", "", 0, "", 91);
