INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (7, 0, "とくに待っていた覚えはないのだけど、\nまあいいわ、ようこそ私の診察室へ。", 0, 1007406, 1007406033, 0.5, 0, 117531, 1, 11);
INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES ("", "", "", "", 1007406, 1007406034, "", "", 0, "", 91);
