INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (6, 0, "いや、結構。\n学院の都合で押しつけられた\n名誉学位などニックネームにも同義だ。", 0, 1007406, 1007406042, 0.5, 0, 111011, 1, 11);
INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES ("", "", "", "", 1007406, 1007406043, "", "", 0, "", 91);
