INSERT INTO `v1_4381ed4cd0c0f749957d12c8c407d4d33eaa1ab62421f654f7233368ea5c533f` VALUES (5, 0, "是非もなし。\nこの脆弱な体で\n一丁前に社会生活を送れているのは、\n一重にミツキ師の助力にほかならない。", 0, 1007406, 1007406052, 0.5, 0, 111011, 1, 11);
